const express = require('express');
const { HTTP } = require('cloudevents');
const crypto = require('crypto');
const { AppDataSource } = require('../dataSource');
const { CustomerSubscription } = require('../entities/CustomerSubscription');

const app = express();
app.use(express.json({ type: ['application/json', 'application/cloudevents+json'] }));

app.post('/webhooks/cloudevents/billing', async (req, res) => {
  // Validate webhook HMAC signature
  const signature = req.headers['x-hub-signature-256'];
  const expectedSig = crypto
    .createHmac('sha256', process.env.BILLING_WEBHOOK_SECRET)
    .update(JSON.stringify(req.body))
    .digest('hex');

  if (!signature || signature !== `sha256=${expectedSig}`) {
    return res.status(401).json({ error: 'Invalid webhook signature' });
  }

  let event;
  try {
    event = HTTP.toEvent({ headers: req.headers, body: req.body });
  } catch (err) {
    return res.status(400).json({ error: 'Malformed CloudEvent' });
  }

  if (event.type === 'com.stripe.subscription.deleted') {
    const subscriptionId = event.subject;

    const subRepo = AppDataSource.getRepository(CustomerSubscription);
    const existingSub = await subRepo.findOne({ where: { subscriptionId } });

    if (existingSub) {
      existingSub.status = 'CANCELLED';
      existingSub.cancelledAt = new Date();
      await subRepo.save(existingSub);
    }
  }

  res.status(200).json({ received: true, id: event.id });
});

app.listen(9006);
